enum LearningLevel { foundation, intermediate, advanced, competitive }
enum LearningSection { numberSense, arithmetic, algebra, geometry, dataAndProbability, advancedMentalMath }

class LessonTopic {
  const LessonTopic({required this.id, required this.title, required this.section, required this.level, required this.summary, this.concepts = const [], this.methods = const [], this.examples = const [], this.traps = const [], this.practice = const []});
  final String id, title, summary;
  final LearningSection section;
  final LearningLevel level;
  final List<String> concepts, methods, examples, traps, practice;
  Map<String,dynamic> toMap()=>{'id':id,'title':title,'section':section.name,'level':level.name,'summary':summary,'concepts':concepts,'methods':methods,'examples':examples,'traps':traps,'practice':practice};
  factory LessonTopic.fromMap(Map<String,dynamic> m)=>LessonTopic(id:m['id']??'',title:m['title']??'',section:LearningSection.values.firstWhere((e)=>e.name==m['section'],orElse:()=>LearningSection.numberSense),level:LearningLevel.values.firstWhere((e)=>e.name==m['level'],orElse:()=>LearningLevel.foundation),summary:m['summary']??'',concepts:_s(m['concepts']),methods:_s(m['methods']),examples:_s(m['examples']),traps:_s(m['traps']),practice:_s(m['practice']));
  static List<String> _s(dynamic v)=>v is List?v.map((e)=>'$e').toList():const[];
}

