  static LessonTopic? byId(String id)=>topics.cast<LessonTopic?>().firstWhere((t)=>t!.id==id,orElse:()=>null);
  static List<LessonTopic> search(String query){final q=query.toLowerCase().trim();if(q.isEmpty)return topics;return topics.where((t)=>t.title.toLowerCase().contains(q)||t.summary.toLowerCase().contains(q)).toList();}
